CodeInjections.CodeInjection:
    float4 placeableColorScale;
    float3 colorTint;
#if defined(REFLECTOR_SHADING)
    float reflectorIntensity;
#endif

    float3 mDeformed = In.position.xyz;
#if defined(VS_FAKE_Y_POS)
    mDeformed.y += decalTerrainDetailOverlayFakeY;
#endif
    return mDeformed.xyz;

#if defined( REFLECTOR_SHADING )
{
    float specDistribution = saturate(shadingAngles.VdotL);
    specDistribution *= specDistribution;
    specDistribution *= specDistribution;
    specDistribution *= specDistribution; // hardcoded power of 8

    float3 retroReflectionShading = globals.gAlpha * specDistribution * diffuseColor * object.reflectorIntensity; // * reflectorIntensity to make it brighter compared to diffuse

    specularShading += retroReflectionShading;
}
#endif

diffuseColor = saturate(diffuseColor + object.colorTint);
if (object.placeableColorScale.w > 0){
    diffuseColor = lerp(diffuseColor,object.placeableColorScale.rgb,saturate(0.1+getFresnel( facing, 0.15 , 4.0 ))*object.placeableColorScale.w);
}

#if defined(ALPHA_BLENDED)
    reflectingLightingScale = alpha;
    #if defined( REFLECTOR_SHADING )
        globals.gAlpha = alpha;
    #endif
#endif
